package com.example.dsatracker.exception;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;@RestControllerAdvicepublic class GlobalExceptionHandler {    @ExceptionHandler(EmailAlreadyExistsException.class)    public ResponseEntity<ErrorResponse> handleEmailAlreadyExists(            EmailAlreadyExistsException ex) {        ErrorResponse error = ErrorResponse.builder()                .timestamp(LocalDateTime.now())                .status(HttpStatus.CONFLICT.value())                .message(ex.getMessage())                .build();        return ResponseEntity.status(HttpStatus.CONFLICT).body(error);    }    @ExceptionHandler(InvalidCredentialsException.class)    public ResponseEntity<ErrorResponse> handleInvalidCredentials(            InvalidCredentialsException ex) {        ErrorResponse error = ErrorResponse.builder()                .timestamp(LocalDateTime.now())                .status(HttpStatus.UNAUTHORIZED.value())                .message(ex.getMessage())                .build();        return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(error);    }    @ExceptionHandler(MethodArgumentNotValidException.class)    public ResponseEntity<ErrorResponse> handleValidationException(            MethodArgumentNotValidException ex) {        String message = ex.getBindingResult()                .getFieldError()                .getDefaultMessage();        ErrorResponse error = ErrorResponse.builder()                .timestamp(LocalDateTime.now())                .status(HttpStatus.BAD_REQUEST.value())                .message(message)                .build();        return ResponseEntity.badRequest().body(error);    }    @ExceptionHandler(Exception.class)    public ResponseEntity<ErrorResponse> handleGenericException(            Exception ex) {        ErrorResponse error = ErrorResponse.builder()                .timestamp(LocalDateTime.now())                .status(HttpStatus.INTERNAL_SERVER_ERROR.value())                .message(ex.getMessage())                .build();        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)                .body(error);    }}